#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXE 10005
#define INF 1000000000000000LL

typedef struct {
    int to;
    int weight;
    int next;
} Edge;

int head[MAXE], edge_cnt;
Edge edges[MAXE * 4];

void add_edge(int u, int v, int w) {
    edges[edge_cnt] = (Edge){v, w, head[u]};
    head[u] = edge_cnt++;
    edges[edge_cnt] = (Edge){u, w, head[v]};
    head[v] = edge_cnt++;
}

int depth[MAXE];
int parent_node[MAXE];
int parent_weight[MAXE];
bool visited[MAXE];

int cycle_id[MAXE];
int cycle_len[MAXE];
int num_cycles = 0;

void find_cycles_dfs(int u, int p, int d) {
    visited[u] = true;
    depth[u] = d;
    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        int w = edges[e].weight;
        if (v == p) continue;
        if (visited[v]) {
            if (depth[v] < depth[u]) {
                num_cycles++;
                int total_len = w;
                cycle_id[u] = num_cycles;
                int curr = u;
                while (curr != v) {
                    total_len += parent_weight[curr];
                    curr = parent_node[curr];
                    cycle_id[curr] = num_cycles;
                }
                cycle_len[num_cycles] = total_len;
            }
        } else {
            parent_node[v] = u;
            parent_weight[v] = w;
            find_cycles_dfs(v, u, d + 1);
        }
    }
}

// Fila de prioridade (Min-Heap) para o algoritmo de Dijkstra
typedef struct {
    int u;
    long long dist;
} HeapNode;

HeapNode heap[MAXE * 20];
int heap_size = 0;

void push(int u, long long d) {
    int i = heap_size++;
    heap[i] = (HeapNode){u, d};
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].dist <= heap[i].dist) break;
        HeapNode tmp = heap[p];
        heap[p] = heap[i];
        heap[i] = tmp;
        i = p;
    }
}

HeapNode pop() {
    HeapNode top = heap[0];
    heap[0] = heap[--heap_size];
    int i = 0;
    while (2 * i + 1 < heap_size) {
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        int best = left;
        if (right < heap_size && heap[right].dist < heap[left].dist) {
            best = right;
        }
        if (heap[i].dist <= heap[best].dist) break;
        HeapNode tmp = heap[i];
        heap[i] = heap[best];
        heap[best] = tmp;
        i = best;
    }
    return top;
}

long long dist[MAXE];
long long min_dist_cycle[MAXE];

int main() {
    int E, R;
    if (scanf("%d %d", &E, &R) != 2) return 0;

    for (int i = 1; i <= E; i++) {
        head[i] = -1;
    }
    edge_cnt = 0;

    for (int i = 0; i < R; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        add_edge(u, v, w);
    }

    // Identificar ciclos
    for (int i = 1; i <= E; i++) {
        if (!visited[i]) {
            find_cycles_dfs(i, 0, 1);
        }
    }

    int K;
    if (scanf("%d", &K) != 1) return 0;

    while (K--) {
        int X, T;
        scanf("%d %d", &X, &T);

        for (int i = 1; i <= E; i++) {
            dist[i] = INF;
        }
        for (int i = 1; i <= num_cycles; i++) {
            min_dist_cycle[i] = INF;
        }

        dist[X] = 0;
        heap_size = 0;
        push(X, 0);

        while (heap_size > 0) {
            HeapNode top = pop();
            int u = top.u;
            long long d = top.dist;

            if (d > dist[u]) continue;

            if (cycle_id[u] > 0) {
                int cid = cycle_id[u];
                if (d < min_dist_cycle[cid]) {
                    min_dist_cycle[cid] = d;
                }
            }

            for (int e = head[u]; e != -1; e = edges[e].next) {
                int v = edges[e].to;
                long long w = edges[e].weight;
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    push(v, dist[v]);
                }
            }
        }

        long long ans = INF;
        for (int i = 1; i <= num_cycles; i++) {
            if (cycle_len[i] >= T && min_dist_cycle[i] < INF) {
                long long cost = 2 * min_dist_cycle[i] + cycle_len[i];
                if (cost < ans) {
                    ans = cost;
                }
            }
        }

        if (ans == INF) {
            printf("-1\n");
        } else {
            printf("%lld\n", ans);
        }
    }

    return 0;
}
